/* A study workspace for every resource: direct loading, readable text and local practice. */
let studio=null,studioGeneration=0,studioLookup=new Map(),studioGuidesPromise=null;
const studioPayloads=new Map();state.resourceWork=state.resourceWork||{};
function readStudyJson(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);return fetch(url,{signal:controller.signal}).then(r=>{if(!r.ok)throw Error('Ressource indisponible');return r.json()}).finally(()=>clearTimeout(timer))}
function getStudyGuides(){if(!studioGuidesPromise)studioGuidesPromise=readStudyJson('./data/learning_guides.json').catch(()=>{studioGuidesPromise=null;return []});return studioGuidesPromise}
async function getStudyPayload(id){if(studioPayloads.has(id))return studioPayloads.get(id);const urls=studyResourceUrls(id);const promise=Promise.all([readStudyJson(urls.metadata).catch(()=>null),urls.article?readStudyJson(urls.article):null]).then(async([meta,article])=>{let r=meta?.resource||article?.resource;if(!r){await loadLibrary();r=studioLookup.get(id)||libraryData?.find(x=>x.id===id)}if(!r||r.id!==id)throw Error('Notice indisponible');return {...meta,resource:r,article}}).catch(e=>{studioPayloads.delete(id);throw e});studioPayloads.set(id,promise);return promise}
loadLibrary=async function(){if(libraryData)return libraryData;if(libraryPromise)return libraryPromise;libraryLoading=true;libraryError='';libraryPromise=(async()=>{try{let rows;try{rows=decodeStudyCatalog(await readStudyJson('./library/catalog-v2.json'))}catch{rows=await readStudyJson('./library/index.json')}if(!Array.isArray(rows))throw Error();libraryData=rows;studioLookup=new Map(rows.map(r=>[r.id,r]));return rows}catch{libraryError='Le catalogue n’est pas disponible. Réessaie avec une connexion.'}finally{libraryLoading=false;libraryPromise=null;if(['explore','downloads'].includes(page)&&!location.hash.includes('/ressource/'))render()}})();return libraryPromise};
const exploreBeforeStudio=exploreView;exploreView=function(){if(location.hash.includes('/ressource/')&&studio)return studioMarkup();return exploreBeforeStudio()};
resourceCard=function(r){const video=r.f==='video';return `<article class="resource-card"><button class="resource-preview ${video?'resource-preview-video':'resource-preview-article'}" data-resource="${r.id}" aria-label="Ouvrir ${esc(r.title)}">${video?`<img src="https://i.ytimg.com/vi/${r.v}/mqdefault.jpg" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer"><span class="resource-preview-play" aria-hidden="true">▷</span>${r.d?`<small>${Math.max(1,Math.ceil(r.d/60))} min</small>`:''}`:'<span aria-hidden="true">Aa</span><small>ARTICLE EN FRANÇAIS</small>'}</button><div class="resource-card-content"><small class="resource-kind">${video?'Vidéo · fiche · pratique':'Article · atelier'}</small><small class="resource-collection">${esc(r.c)}</small><h3><button data-resource="${r.id}">${esc(r.title)}</button></h3><p>${video?'Khan Academy':'MDN Web Docs'} · français</p></div><div class="resource-card-actions"><button data-resource="${r.id}">${state.resourceDone.includes(r.id)?'✓ Revoir':'Ouvrir la leçon'} →</button>${!video?`<button data-save-resource="${r.id}" aria-label="Enregistrer ${esc(r.title)} hors ligne">${icon(state.resourceSaved.includes(r.id)?'check':'download')}</button>`:''}</div></article>`};
openResource=async function(id,push=true){if(!validStudyResourceId(id)){toast('Cette ressource n’est pas reconnue.');return}const generation=++studioGeneration;closeModal();stopRuntime();academySection=null;selectedDetail=null;selectedSector=null;page='explore';if(push)history.pushState({},'','#/ressource/'+id);const known=studioLookup.get(id)||libraryData?.find(r=>r.id===id);studio={id,resource:known||{id,title:'Ouverture de la leçon…',f:id.startsWith('ka-')?'video':'article'},loading:true,tab:'read',step:0,part:0};resourceCurrent=known||null;render();if($('#sidebar'))$('#sidebar').scrollTop=0;window.scrollTo({top:0,behavior:'instant'});try{const [payload,guides]=await Promise.all([getStudyPayload(id),getStudyGuides()]);if(generation!==studioGeneration||!location.hash.includes('/ressource/'+id))return;const r=payload.resource;studio={...studio,resource:r,payload,guide:matchLearningGuide(r,guides),parts:payload.article?splitStudyArticle(payload.article.html):[],loading:false};resourceCurrent=r;const work=state.resourceWork[id];if(work?.tab)studio.tab=['read','steps','practice'].includes(work.tab)?work.tab:'read';render();eventLocal('resource_open',{resourceId:id})}catch{if(generation!==studioGeneration)return;studio.loading=false;studio.error=true;render()}};
function splitStudyArticle(html){const safe=safeArticle(html),doc=new DOMParser().parseFromString(safe,'text/html'),parts=[];let current={title:'Comprendre la notion',html:''};for(const node of doc.body.childNodes){if(node.nodeType===1&&['H1','H2'].includes(node.tagName)&&current.html.trim()){parts.push(current);current={title:node.textContent.trim(),html:''}}current.html+=node.outerHTML||esc(node.textContent||'')}if(current.html.trim())parts.push(current);return parts.length?parts:[{title:'L’article',html:safe}]}
function studyWork(){if(!studio)return {};return state.resourceWork[studio.id]||(state.resourceWork[studio.id]={title:studio.resource.title,answer:'',application:'',checks:[],quiz:{},tab:'read'})}
function plainStudyDescription(){if(!studio?.payload?.descriptionHtml)return '';const d=new DOMParser().parseFromString(safeArticle(studio.payload.descriptionHtml),'text/html');return d.body.textContent.trim()}
function studioMarkup(){const r=studio.resource,work=state.resourceWork[studio.id]||{},complete=state.resourceDone.includes(studio.id);if(studio.error)return `<section class="study-error"><button class="back-link" data-study-action="back">← Bibliothèque</button><h1>La leçon n’a pas pu s’ouvrir.</h1><p>Si tu es hors ligne, choisis une ressource déjà enregistrée.</p><button class="primary" data-study-action="retry">Réessayer</button></section>`;return `<section class="study-page"><div class="study-breadcrumb"><button data-study-action="back">Bibliothèque</button><span>/</span><span>${esc(r.c||'Ressource')}</span><span class="study-saved">${complete?'✓ Étudiée':''}</span></div><header class="study-heading"><div><span class="eyebrow">${r.f==='video'?'KHAN ACADEMY · VIDÉO EN FRANÇAIS':'MDN · ARTICLE EN FRANÇAIS'}</span><h1>${esc(r.title)}</h1>${r.u?`<p>${esc(r.u)}</p>`:''}</div><button class="secondary study-save" data-study-action="save">${icon('download')}<span>${state.resourceSaved.includes(r.id)?'Enregistrée':'Hors ligne'}</span></button></header>${studio.loading?`<div class="study-skeleton" role="status"><div></div><div></div><span>Préparation de ton espace…</span></div>`:`<div class="study-layout ${r.f==='article'?'study-article-layout':''}"><aside class="study-media">${r.f==='video'?`<div class="study-video" id="studio-video">${studio.playing?studyVideoIframe():`<button data-study-action="play" class="study-play" aria-label="Lire ${esc(r.title)}"><span aria-hidden="true">▷</span><strong>Voir la vidéo</strong><small>${r.d?Math.ceil(r.d/60)+' min · ':''}audio français · lecture à ton choix</small></button>`}</div><div class="study-media-note"><span>Une autre explication, si tu en as besoin.</span><button data-study-tab="practice">Passer à la pratique →</button></div>`:`<div class="study-outline"><span class="eyebrow">DANS CET ARTICLE</span>${studio.parts.map((p,i)=>`<button data-study-part="${i}" class="${studio.part===i?'current':''}" aria-current="${studio.part===i?'location':'false'}"><span>${String(i+1).padStart(2,'0')}</span>${esc(p.title)}</button>`).join('')}</div>`}<div class="study-journey"><h2>Ton chemin</h2><div><span>01</span><button data-study-tab="read">Comprendre</button><i>${work.read?'✓':''}</i></div><div><span>02</span><button data-study-tab="steps">Avancer pas à pas</button><i>${work.steps?'✓':''}</i></div><div><span>03</span><button data-study-tab="practice">Essayer et expliquer</button><i>${complete?'✓':''}</i></div></div>${studyRelatedMarkup()}</aside><section class="study-content"><nav class="study-tabs" aria-label="Étapes d’apprentissage">${[['read','Lire'],['steps','Pas à pas'],['practice','Pratiquer']].map(([key,label])=>`<button data-study-tab="${key}" class="${studio.tab===key?'active':''}" aria-pressed="${studio.tab===key}">${label}${key==='practice'&&studio.guide?'<span>1 défi</span>':''}</button>`).join('')}</nav><div id="studio-panel" class="study-panel">${studio.tab==='read'?studyReading():studio.tab==='steps'?studySteps():studyPractice()}</div><details class="study-source"><summary>Sources et crédits</summary><p>${r.p==='mdn'?'MDN Web Docs et ses contributeurs · texte CC BY-SA 2.5. Mise en forme adaptée, images et démonstrations tierces omises.':'Khan Academy et ses contributeurs · CC BY-NC-SA. Vidéo et présentation issues de l’export public français ; aucune transcription intégrale n’est annoncée.'}</p><p>Les fiches de notion, étapes et exercices Nunya sont des compléments originaux à relire. La correspondance avec le programme togolais n’est pas certifiée.</p><a href="${esc(r.url||studio.payload.sourceUrl)}" target="_blank" rel="noopener">Source d’origine ↗</a> · <a href="${r.p==='mdn'?'https://creativecommons.org/licenses/by-sa/2.5/':'https://creativecommons.org/licenses/by-nc-sa/3.0/'}" target="_blank" rel="noopener">Licence ↗</a></details></section></div>`}</section>`}
function studyVideoIframe(){const r=studio.resource;return `<iframe src="https://www.youtube-nocookie.com/embed/${r.v}?rel=0&hl=fr&playsinline=1" title="${esc(r.title)}" allow="encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`}
function studyReading(){const r=studio.resource,g=studio.guide;if(r.f==='article'){const part=studio.parts[studio.part];return `<div class="study-reading-top"><span>Texte complet · partie ${studio.part+1}/${studio.parts.length}</span><select id="study-part-select" aria-label="Partie de l’article">${studio.parts.map((p,i)=>`<option value="${i}" ${studio.part===i?'selected':''}>${i+1}. ${esc(p.title)}</option>`).join('')}</select></div><div class="article-reader">${part.html}</div><div class="study-part-actions"><button class="secondary" data-study-action="prev-part" ${studio.part===0?'disabled':''}>← Précédent</button><button class="secondary" data-study-action="next-part" ${studio.part===studio.parts.length-1?'disabled':''}>Suite →</button></div>${studyCodingAvailable()?'<button class="text-button" data-study-action="code">Modifier et tester un exemple ici →</button>':''}<div class="study-next"><button class="primary" data-study-tab="steps">Compris, je passe aux étapes →</button></div>`}const desc=plainStudyDescription();return `${g?`<span class="eyebrow">L’IDÉE À COMPRENDRE</span><h2>${esc(g.title)}</h2><p class="study-prose">${esc(g.body)}</p><div class="study-example"><span>Un exemple concret</span><pre><code>${esc(g.example)}</code></pre><p>${esc(g.output)}</p></div>${desc?`<details class="study-context"><summary>Le contexte de cette vidéo</summary><div>${safeArticle(studio.payload.descriptionHtml)}</div></details>`:''}`:`<span class="eyebrow">POUR ABORDER LA NOTION</span><h2>${esc(r.title)}</h2>${desc?`<div class="study-prose">${safeArticle(studio.payload.descriptionHtml)}</div>`:`<p>Observe l’explication et relève une idée importante sur « ${esc(r.title)} ». Le carnet de pratique t’aide à l’expliquer avec tes mots.</p>`}<div class="study-reading-prompt"><h3>Ta question de départ</h3><p>Quelle idée veux-tu comprendre dans cette leçon ? Garde un exemple pour vérifier ton explication à la fin.</p></div>`}<div class="study-next"><button class="primary" data-study-tab="steps">Voir les étapes →</button></div>`}
function studySteps(){const g=studio.guide,steps=g?.steps||[{title:'Repérer la notion',text:plainStudyDescription()||'Lis le début de l’article et identifie la notion expliquée.'},{title:'Choisir un exemple',text:studio.resource.f==='article'?'Reviens au texte et choisis un exemple ou un passage. Note ses données, sa règle et ce qu’il permet de comprendre.':'Dans la vidéo, choisis un exemple. Fais une pause avant le résultat, puis essaie d’expliquer la prochaine étape.'},{title:'Vérifier ton explication',text:'Reprends l’exemple avec tes mots. Compare ensuite ton raisonnement au contenu de la leçon et note une question qui reste ouverte.'}];studio.step=Math.max(0,Math.min(steps.length-1,studio.step));const step=steps[studio.step];return `<span class="eyebrow">UNE ÉTAPE À LA FOIS</span><div class="study-step-progress">${steps.map((_,i)=>`<button data-study-step="${i}" class="${i<=studio.step?'filled':''}" aria-label="Étape ${i+1}"></button>`).join('')}</div><small>Étape ${studio.step+1} sur ${steps.length}</small><h2>${esc(step.title)}</h2>${step.code?`<pre><code>${esc(step.code)}</code></pre>`:`<p class="study-prose">${esc(step.text)}</p>`}<div class="study-next"><button class="secondary" data-study-action="prev-step" ${studio.step===0?'disabled':''}>← Revenir</button>${studio.step===steps.length-1?'<button class="primary" data-study-tab="practice">À moi d’essayer →</button>':'<button class="primary" data-study-action="next-step">Continuer →</button>'}</div>`}
function studyPractice(){const w=studyWork(),q=studio.guide?.questions[0],result=q&&Number.isInteger(w.quiz?.answer)?studyQuestionResult(q,w.quiz.answer):null;return `<span class="eyebrow">ESSAIS ILLIMITÉS · SANS PRESSION</span><h2>À toi de faire le lien.</h2>${q?`<section class="study-quiz"><h3>${esc(q.question)}</h3><div class="study-options">${q.options.map((text,i)=>`<button data-study-answer="${i}" aria-pressed="${w.selected===i}" class="${w.selected===i?'selected':''}"><span>${String.fromCharCode(65+i)}</span>${esc(text)}</button>`).join('')}</div><button class="primary" data-study-action="check" ${!Number.isInteger(w.selected)?'disabled':''}>Vérifier ma réponse</button>${result?`<div class="study-feedback" role="status"><strong>${result.correct?'✓ Bien vu !':'Une piste pour réessayer'}</strong><p>${esc(result.explanation)}</p></div>`:''}</section>`:`<p>Appuie-toi sur le contenu de cette leçon. Les réponses ci-dessous sont une auto-évaluation, sans correction automatique inventée.</p>`}<section class="study-reflection"><label for="studio-answer">Comment expliquerais-tu « ${esc(studio.resource.title)} » à un camarade ?</label><textarea id="studio-answer" rows="4" maxlength="4000" placeholder="L’idée, avec mes propres mots…">${esc(w.answer||'')}</textarea><label for="studio-application">Un exemple, un raisonnement ou une application</label><textarea id="studio-application" rows="3" maxlength="4000" placeholder="Un exemple que je peux expliquer…">${esc(w.application||'')}</textarea><button class="text-button" data-study-action="reference">${w.showReference?'Masquer le repère':'Comparer avec un repère de la leçon'} ↓</button>${w.showReference?`<div class="study-reference"><strong>Un repère pour te relire</strong><p>${esc(studyReferenceText())}</p><small>Compare les idées ; il n’est pas nécessaire de reprendre les mêmes phrases.</small></div>`:''}<div class="study-selfcheck">${['J’ai expliqué une idée précise.','J’ai donné un exemple ou une étape.','Je sais ce que je dois encore revoir.'].map((label,i)=>`<label><input type="checkbox" data-study-check="${i}" ${w.checks?.[i]?'checked':''}>${label}</label>`).join('')}</div><div class="study-next"><button class="secondary" data-study-action="save-work">Garder mon travail</button><button class="primary" data-study-action="complete">${state.resourceDone.includes(studio.id)?'✓ Étape étudiée':'Terminer cette étape'}</button></div><p class="study-local" id="studio-save-status" role="status">Ton travail reste sur cet appareil.</p></section>`}
function studyReferenceText(){if(studio.guide)return studio.guide.body;const desc=plainStudyDescription();if(desc)return desc;const doc=new DOMParser().parseFromString(safeArticle(studio.payload.article?.html||''),'text/html');return [...doc.querySelectorAll('p')].map(p=>p.textContent.trim()).filter(t=>t.length>70).slice(0,2).join('\n')||'Reviens à un passage de l’article et vérifie que ton explication utilise la notion dans le même sens.'}
function studyRelatedMarkup(){const rows=studio.payload?.related||[];return rows.length?`<section class="study-related"><h2>Dans la même collection</h2>${rows.map(r=>`<button data-resource="${r.id}"><span>${r.f==='video'?'▷':'Aa'}</span>${esc(r.title)}<b>→</b></button>`).join('')}</section>`:''}
function studyCodingAvailable(){const r=studio?.resource;return r?.f==='article'&&/javascript|html|css|scripting/i.test(r.url||'')&&studio.parts?.[studio.part]?.html.includes('<pre>')}
function renderStudyPanel(){if(!studio)return;const panel=$('#studio-panel');if(!panel){render();return}studyWork().tab=studio.tab;panel.innerHTML=studio.tab==='read'?studyReading():studio.tab==='steps'?studySteps():studyPractice();$$('.study-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.studyTab===studio.tab);b.setAttribute('aria-pressed',String(b.dataset.studyTab===studio.tab))});$$('.study-outline button').forEach(b=>{const active=Number(b.dataset.studyPart)===studio.part;b.classList.toggle('current',active);b.setAttribute('aria-current',active?'location':'false')});const w=studyWork();$$('.study-journey>div>i').forEach((n,i)=>n.textContent=(i===0?w.read:i===1?w.steps:state.resourceDone.includes(studio.id))?'✓':'');if($('.study-saved'))$('.study-saved').textContent=state.resourceDone.includes(studio.id)?'✓ Étudiée':'';if($('.study-save span'))$('.study-save span').textContent=state.resourceSaved.includes(studio.id)?'Enregistrée':'Hors ligne';wireStudyLinks()}

function wireStudyLinks(){if(!studio||studio.loading)return;$$('.article-reader a').forEach(a=>{const href=a.getAttribute('href')||'';if(/^(https:\/\/developer\.mozilla\.org)?\/fr\/docs\//.test(href)){a.dataset.studySlug=href.replace(/^(https:\/\/developer\.mozilla\.org)?\/fr\/docs\//,'').split('#')[0];a.href='#';}else if(href.startsWith('#')){a.dataset.studyAnchor=href.slice(1);a.href='#';}else{a.target='_blank';a.rel='noopener'}})}
const renderWithStudio=render;render=function(){renderWithStudio();if(studio&&location.hash.includes('/ressource/')){document.body.classList.add('resource-study');$('#breadcrumb-current').textContent='Apprendre';wireStudyLinks()}else document.body.classList.remove('resource-study')};
let studySaveTimer;function persistStudyWork(){if(!studio)return;const w=studyWork();w.title=studio.resource.title;w.updatedAt=new Date().toISOString();persist();const status=$('#studio-save-status');if(status)status.textContent='Enregistré sur cet appareil.'}
function setStudyTab(tab){if(!studio||studio.loading)return;const w=studyWork();if(studio.tab==='read')w.read=true;if(studio.tab==='steps')w.steps=true;studio.tab=tab;w.tab=tab;persistStudyWork();renderStudyPanel()}
saveResource=async function(id){try{const payload=await getStudyPayload(id),urls=studyResourceUrls(id);if(!urls.article){const cache=await caches.open('nunya-library-v1');await cache.addAll([urls.metadata,'./library/catalog-v2.json','./data/learning_guides.json']);if(!state.resourceSaved.includes(id))state.resourceSaved.push(id);persist();toast('Fiche enregistrée. La vidéo nécessite une connexion.');if(studio?.id===id)renderStudyPanel();return}const cache=await caches.open('nunya-library-v1');await cache.addAll([urls.metadata,urls.article,'./library/catalog-v2.json','./library/manifest.json','./data/learning_guides.json']);if(!state.resourceSaved.includes(payload.resource.id))state.resourceSaved.push(id);persist();toast('Article et activités enregistrés pour le hors ligne.');if(studio?.id===id)renderStudyPanel()}catch{toast('Enregistrement indisponible. Vérifie ta connexion et ton espace de stockage.')}};
document.addEventListener('input',e=>{if(!studio||!['studio-answer','studio-application'].includes(e.target.id))return;studyWork()[e.target.id==='studio-answer'?'answer':'application']=e.target.value.slice(0,4000);clearTimeout(studySaveTimer);studySaveTimer=setTimeout(persistStudyWork,500)});
document.addEventListener('change',e=>{if(!studio)return;if(e.target.dataset.studyCheck!==undefined){studyWork().checks[Number(e.target.dataset.studyCheck)]=e.target.checked;persistStudyWork()}if(e.target.id==='study-part-select'){studio.part=Number(e.target.value);studio.tab='read';renderStudyPanel()}});
document.addEventListener('click',async e=>{const a=e.target.closest('a[data-study-slug],a[data-study-anchor]');if(a){e.preventDefault();e.stopImmediatePropagation();if(a.dataset.studySlug){const slug=decodeURI(a.dataset.studySlug),hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(slug)),id='mdn-'+[...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('').slice(0,16);openResource(id)}else{const target=learningNormalize(decodeURI(a.dataset.studyAnchor)).replace(/[_-]/g,' '),part=studio.parts?.findIndex(p=>{const d=new DOMParser().parseFromString(p.html,'text/html');return [...d.querySelectorAll('h1,h2,h3,h4')].some(h=>learningNormalize(h.textContent).replace(/[_-]/g,' ')===target)});if(part>=0){studio.part=part;studio.tab='read';renderStudyPanel();$('#studio-panel').scrollIntoView({block:'start'})}else toast('Cette section n’est pas disponible dans le texte importé.')}return}const b=e.target.closest('button');if(!b||!studio)return;if(b.dataset.studyTab){e.stopImmediatePropagation();setStudyTab(b.dataset.studyTab);return}if(b.dataset.studyPart!==undefined){e.stopImmediatePropagation();studio.part=Number(b.dataset.studyPart);studio.tab='read';renderStudyPanel();return}if(b.dataset.studyStep!==undefined){e.stopImmediatePropagation();studio.step=Number(b.dataset.studyStep);renderStudyPanel();return}if(b.dataset.studyAnswer!==undefined){e.stopImmediatePropagation();const w=studyWork();w.selected=Number(b.dataset.studyAnswer);w.quiz={};renderStudyPanel();return}const action=b.dataset.studyAction;if(!action)return;e.stopImmediatePropagation();if(action==='back'){studioGeneration++;studio=null;resourceCurrent=null;navigate('explore');return}if(action==='retry'){openResource(studio.id,false);return}if(action==='play'){studio.playing=true;$('#studio-video').innerHTML=studyVideoIframe();return}if(action==='save'){await saveResource(studio.id);return}if(action==='next-step'||action==='prev-step'){studio.step+=action==='next-step'?1:-1;renderStudyPanel();return}if(action==='next-part'||action==='prev-part'){studio.part+=action==='next-part'?1:-1;renderStudyPanel();return}if(action==='check'){const q=studio.guide?.questions[0],w=studyWork(),result=studyQuestionResult(q,w.selected);if(result){w.quiz={answer:w.selected,correct:result.correct};w.needsReview=!result.correct;persistStudyWork();renderStudyPanel()}return}if(action==='reference'){studyWork().showReference=!studyWork().showReference;renderStudyPanel();return}if(action==='save-work'){persistStudyWork();toast('Ton raisonnement est enregistré.');return}if(action==='complete'){const w=studyWork();if(studio.guide&&!w.quiz?.correct){toast('Essaie le défi et utilise sa correction avant de terminer.');return}if((w.answer||'').trim().length<15){toast('Écris une courte explication avec tes mots avant de terminer.');$('#studio-answer')?.focus();return}if(!state.resourceDone.includes(studio.id))state.resourceDone.push(studio.id);w.needsReview=false;persistStudyWork();renderStudyPanel();toast('Une étape de plus. Tu peux continuer dans la même collection.');return}if(action==='code'){resourceCurrent=studio.resource;workshop();const panel=$('#article-code-panel');if(panel)panel.insertAdjacentHTML('afterbegin','<p class="study-local">JavaScript sans DOM ni réseau ; HTML/CSS en aperçu isolé. Certains exemples de référence demandent un contexte supplémentaire.</p>');return}},true);
function restoreStudyProgress(data){if(!data||typeof data!=='object'||Array.isArray(data))return;for(const [id,w]of Object.entries(data).slice(0,2000)){if(!validStudyResourceId(id)||!w||typeof w!=='object')continue;state.resourceWork[id]={title:String(w.title||'Ressource').slice(0,250),answer:String(w.answer||'').slice(0,4000),application:String(w.application||'').slice(0,4000),checks:Array.isArray(w.checks)?w.checks.slice(0,3).map(Boolean):[],quiz:{},tab:['read','steps','practice'].includes(w.tab)?w.tab:'read',needsReview:!!w.needsReview,updatedAt:String(w.updatedAt||'').slice(0,30)}}}
const reviewBeforeStudio=reviewView;reviewView=function(){const rows=Object.entries(state.resourceWork).filter(([,w])=>w.needsReview);return reviewBeforeStudio()+(rows.length?`<section class="panel"><h3>Mes notions à reprendre</h3>${rows.slice(-8).map(([id,w])=>`<div class="saved-row"><button data-resource="${id}">${esc(w.title)} →</button><small>Reprendre le défi</small></div>`).join('')}</section>`:'')};
let prefetchTimer;document.addEventListener('pointerover',e=>{const b=e.target.closest('button[data-resource]');if(!b||!validStudyResourceId(b.dataset.resource))return;clearTimeout(prefetchTimer);prefetchTimer=setTimeout(()=>getStudyPayload(b.dataset.resource).catch(()=>{}),180)});document.addEventListener('pointerout',()=>clearTimeout(prefetchTimer));document.addEventListener('focusin',e=>{const id=e.target.closest('button[data-resource]')?.dataset.resource;if(validStudyResourceId(id))getStudyPayload(id).catch(()=>{})});
if(location.hash.includes('/ressource/'))routeAcademy();
